'use strict';
const net={mode:'solo',session:null,busy:false,lastPoll:0,seq:0,commandId:0,pending:[],suppressNotice:false,localPause:false,lastSuccess:0,lastRevision:-1};
const originals={start:startGame,lobby,update,useSkill,buy,sell,attack:attackPlayer,recall,pause};
const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function networkMessage(message){$('networkMessage').textContent=message;}
function selectMode(mode){if(net.session){networkMessage('ออกจากห้องก่อนเปลี่ยนโหมด');return;}net.mode=mode;$('soloMode').classList.toggle('active',mode==='solo');$('onlineMode').classList.toggle('active',mode==='online');$('soloMode').setAttribute('aria-pressed',String(mode==='solo'));$('onlineMode').setAttribute('aria-pressed',String(mode==='online'));$('onlineSetup').hidden=mode!=='online';$('difficulty').disabled=mode==='online';$('startBtn').disabled=mode==='online';$('startBtn').innerHTML=mode==='solo'?'เข้าสู่สนามรบ <span>5v5</span>':'สร้างห้องหรือเข้าห้องก่อน';networkMessage(mode==='online'?'เลือกทีมและตำแหน่งก่อนเข้าห้อง':'');}
function roomConfig(){return {name:$('playerName').value,team:Number($('teamSelect').value),position:$('position').value,hero:selected.id,rune:$('rune').value,enchant:$('enchant').value};}
async function requestApi(path,method='GET',bodyValue,session=net.session){const headers={};if(bodyValue!==undefined)headers['content-type']='application/json';if(session)headers.authorization='Bearer '+session.token;const response=await fetch('/api/'+path,{method,headers,body:bodyValue===undefined?undefined:JSON.stringify(bodyValue),signal:AbortSignal.timeout(7000)});const data=await response.json();if(!response.ok)throw Error(data.error||'เชื่อมต่อไม่สำเร็จ');return data;}
async function enterRoom(create){if(net.session)return;const code=$('roomCode').value.trim().toUpperCase();if(!create&&!/^[A-Z0-9]{6}$/.test(code)){networkMessage('กรอกรหัสห้อง 6 ตัว');return;}$('createRoomBtn').disabled=$('joinRoomBtn').disabled=true;networkMessage('กำลังเชื่อมต่อห้อง...');try{net.session=await requestApi(create?'rooms':`rooms/${code}/join`,'POST',roomConfig(),null);net.seq=0;net.commandId=0;net.pending=[];net.lastRevision=-1;net.lastSuccess=Date.now();net.lastPoll=0;$('roomCreate').hidden=true;$('roomInfo').hidden=false;$('roomCodeLabel').textContent=net.session.code;$('connectionBadge').hidden=false;$('connectionBadge').textContent='ห้อง '+net.session.code;$('startBtn').disabled=!net.session.host;$('startBtn').textContent=net.session.host?'เริ่มแมตช์ออนไลน์':'รอเจ้าของห้องเริ่มเกม';networkMessage('ยืนยันตัวเลือกก่อนเริ่มเกม · บอตจะเติมตำแหน่งว่าง');await pollRoom();}catch(error){networkMessage(error.message);}finally{$('createRoomBtn').disabled=$('joinRoomBtn').disabled=false;}}
function renderMembers(members){$('roomMembers').innerHTML=[0,1].map(team=>`<div class="room-team"><h3 style="color:${team===0?BLUE:RED}">ทีม${team===0?'ฟ้า':'ส้ม'}</h3>${Object.keys(POSITIONS).map(pos=>{const m=members.find(m=>m.team===team&&m.position===pos),h=m&&HEROES.find(h=>h.id===m.hero);return `<div class="room-member">${POSITIONS[pos]} · ${m?escapeText(m.name)+' <span>'+escapeText(h?.name||'')+'</span>':'<span>บอต</span>'}</div>`;}).join('')}</div>`).join('');}
function serializeMatch(){return {time:game.time,paused:game.paused,finished:game.finished,winner:game.winner,entities:game.entities.map(e=>{const clean={...e};delete clean.control;delete clean.targetX;delete clean.targetY;return clean;}),kills:game.kills,wave:game.wave,nextId:game.nextId,towerKills:game.towerKills,effects:effects.slice(-40),ack:Object.fromEntries(game.entities.filter(e=>e.clientId).map(e=>[e.clientId,e.lastCommand||0]))};}
function configureRoster(members){game.entities=game.entities.filter(e=>e.type!=='hero');const defaults={off:'sentinel',mid:'arcanist',carry:'ranger',jungle:'shade',roam:'oracle'};for(let team=0;team<2;team++)for(const position of Object.keys(POSITIONS)){const m=members.find(m=>m.team===team&&m.position===position),def=HEROES.find(h=>h.id===(m?.hero||defaults[position])),e=hero(team,laneFor(position),def,m?.id===net.session.playerId);applyLoadout(e,m?.rune||'power',m?.enchant||'fury',position);if(m){e.clientId=m.id;e.clientName=m.name;e.remoteHuman=!e.player;e.lastCommand=0;e.control={move:{x:0,y:0},attack:false};}if(e.player)game.player=e;game.entities.push(e);}chooseHero(game.player.def.id);$('position').value=game.player.position;setTeamLabels();}
function setTeamLabels(){const blue=document.querySelector('.team.blue'),red=document.querySelector('.team.orange');blue.firstChild.textContent=game.player.team===0?'ทีมคุณ ':'ศัตรู ';red.lastChild.textContent=game.player.team===1?' ทีมคุณ':' ศัตรู';$('qName').textContent=game.player.def.q;$('eName').textContent=game.player.def.e;}
async function beginOnline(){if(!net.session?.host)return;$('startBtn').disabled=true;try{const data=await requestApi(`rooms/${net.session.code}`);$('difficulty').value='normal';originals.start();configureRoster(data.members);await requestApi(`rooms/${net.session.code}/start`,'POST',{state:serializeMatch()});$('modeLabel').textContent='ออนไลน์ · ห้อง '+net.session.code;net.lastSuccess=Date.now();}catch(error){originals.lobby();$('startBtn').disabled=false;networkMessage(error.message);}}
function acceptSnapshot(state){const old=game?.entities||[],wasFinished=game?.finished;const entities=state.entities.map(e=>{const previous=old.find(o=>o.id===e.id),local=e.clientId===net.session.playerId;const next={...e,player:local,remoteHuman:!!e.clientId&&!local};if(e.type==='hero'){next.def=HEROES.find(h=>h.id===e.def?.id)||HEROES[0];next.inventory=(e.inventory||[]).map(i=>ITEMS.find(item=>item.id===i.id)).filter(Boolean);}next.targetX=e.x;next.targetY=e.y;if(previous&&!e.dead&&!previous.dead&&distance(previous,e)<180){next.x=previous.x;next.y=previous.y;}return next;});const player=entities.find(e=>e.clientId===net.session.playerId);if(!player)throw Error('ไม่พบตัวละครของคุณในห้อง');game={...state,entities,player};effects=(state.effects||[]).map(e=>({...e}));const ack=state.ack?.[net.session.playerId]||0;net.pending=net.pending.filter(c=>c.id>ack);$('lobby').hidden=true;$('playerHud').hidden=false;$('pauseBtn').hidden=false;$('shopBtn').hidden=false;document.body.classList.add('playing');$('modeLabel').textContent='ออนไลน์ · ห้อง '+net.session.code;setTeamLabels();syncHud();if(state.paused)$('phase').textContent='เจ้าของห้องพักเกม';if(state.finished&&!wasFinished)showResult();}
function queueCommand(kind,extra={}){if(!net.session||net.session.host)return false;if(net.pending.length>=24){notify('กำลังส่งคำสั่ง รอสักครู่');return false;}net.pending.push({id:++net.commandId,kind,...extra});return true;}
function localInput(){const blocked=net.localPause||$('help').open||document.body.classList.contains('shop-open')||document.hidden;let x=blocked?0:(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystick.x,y=blocked?0:(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystick.y;const len=Math.hypot(x,y);if(len>1){x/=len;y/=len;}return {seq:++net.seq,move:{x,y},aim:pointer,attack:!blocked&&keys.has(' '),commands:net.pending};}
function applyRemoteInputs(members){for(const e of game.entities.filter(e=>e.remoteHuman)){const member=members.find(m=>m.id===e.clientId);if(!member){e.remoteHuman=false;e.clientId=null;e.clientName=null;continue;}let input;try{input=JSON.parse(member.input);}catch{input={};}e.control=Date.now()-member.seen_at>2000?{move:{x:0,y:0},attack:false}:{...input,move:input.move||{x:0,y:0}};for(const cmd of input.commands||[]){if(cmd.id<=(e.lastCommand||0))continue;e.lastCommand=cmd.id;net.suppressNotice=true;try{if(['q','w','e'].includes(cmd.kind))originals.useSkill(cmd.kind,e,input.aim);if(cmd.kind==='buy')originals.buy(cmd.item,e);if(cmd.kind==='sell')originals.sell(cmd.slot,e);if(cmd.kind==='recall'&&!e.dead&&!game.paused){e.recall=4;e.destination=null;}if(cmd.kind==='walk'&&!e.dead&&!game.paused){e.destination={x:Math.max(45,Math.min(WIDTH-45,cmd.point.x)),y:Math.max(45,Math.min(HEIGHT-45,cmd.point.y))};e.recall=0;}if(cmd.kind==='attack'&&!e.dead&&!game.paused)strike(e,enemies(e,e.range,true).filter(t=>t.type!=='base'||baseOpen(t.team)).sort((a,b)=>distance(e,a)-distance(e,b))[0]);}finally{net.suppressNotice=false;}}}}
async function pollRoom(){if(!net.session||net.busy)return;const session=net.session;net.busy=true;try{const data=await requestApi(`rooms/${session.code}`);if(net.session!==session)return;net.lastSuccess=Date.now();$('connectionBadge').textContent='ห้อง '+session.code+' · เชื่อมต่อแล้ว';if(data.status==='closed'){await leaveRoom(false);networkMessage('เจ้าของห้องปิดห้องแล้ว');return;}if(data.status==='waiting'){renderMembers(data.members);await requestApi(`rooms/${session.code}/input`,'POST',{seq:++net.seq,move:{x:0,y:0},commands:[]});}else if(session.host&&game){applyRemoteInputs(data.members);await requestApi(`rooms/${session.code}/state`,'POST',{state:serializeMatch()});}else if(data.state){if(Date.now()-data.updatedAt>12000){$('connectionBadge').textContent='รอเจ้าของห้องกลับมา';notify('เจ้าของห้องขาดการเชื่อมต่อ');}if(data.revision!==net.lastRevision){acceptSnapshot(data.state);net.lastRevision=data.revision;}if(!game.finished)await requestApi(`rooms/${session.code}/input`,'POST',localInput());}}catch(error){if(net.session===session){$('connectionBadge').textContent='กำลังเชื่อมต่อใหม่';networkMessage(error.message);if(game)notify('การเชื่อมต่อสะดุด · กำลังลองใหม่');}}finally{net.busy=false;}}
async function leaveRoom(send=true){const session=net.session;net.session=null;net.pending=[];net.localPause=false;net.busy=false;net.lastRevision=-1;originals.lobby();$('connectionBadge').hidden=true;$('roomCreate').hidden=false;$('roomInfo').hidden=true;$('roomMembers').innerHTML='';$('startBtn').disabled=net.mode==='online';$('startBtn').textContent=net.mode==='online'?'สร้างห้องหรือเข้าห้องก่อน':'เข้าสู่สนามรบ';if(send&&session)try{await requestApi(`rooms/${session.code}/leave`,'POST',{},session);}catch{}networkMessage('');}
startGame=function(){if(net.mode==='online')return beginOnline();return originals.start();};
lobby=function(){if(net.session)return leaveRoom();return originals.lobby();};
update=function(dt){if(net.session&&!net.session.host){if(game){for(const e of game.entities){if(Number.isFinite(e.targetX)){const f=Math.min(1,dt*14);e.x+=(e.targetX-e.x)*f;e.y+=(e.targetY-e.y)*f;}}effects.forEach(e=>e.life-=dt);effects=effects.filter(e=>e.life>0);noticeTimer-=dt;if(noticeTimer<=0)$('announcement').classList.remove('show');}return;}return originals.update(dt);};
useSkill=function(key,actor=null,aim=pointer){if(actor||!net.session||net.session.host)return originals.useSkill(key,actor,aim);if(!game||game.finished||game.player.dead||game.paused||net.localPause)return false;return queueCommand(key);};
buy=function(id,actor=null){if(actor||!net.session||net.session.host)return originals.buy(id,actor);if(!ITEMS.some(i=>i.id===id))return {ok:false,reason:'ไม่พบไอเทม'};if(!game||game.finished||game.player.gold<ITEMS.find(i=>i.id===id).cost||game.player.inventory.length>=6)return {ok:false};queueCommand('buy',{item:id});return {ok:true,pending:true};};
sell=function(slot,actor=null){if(actor||!net.session||net.session.host)return originals.sell(slot,actor);if(!game||!game.player.inventory[slot])return {ok:false};queueCommand('sell',{slot});return {ok:true,pending:true};};
attackPlayer=function(){if(!net.session||net.session.host)return originals.attack();if(game&&!game.finished&&!game.player.dead&&!game.paused&&!net.localPause)queueCommand('attack');};
recall=function(){if(!net.session||net.session.host)return originals.recall();if(game&&!game.finished&&!game.player.dead&&!game.paused&&!net.localPause)queueCommand('recall');};
pause=function(value){$('pauseMessage').textContent=net.session?(net.session.host?'ทุกคนจะพักเกมพร้อมคุณ · เปิดแท็บนี้ไว้เพื่อเล่นต่อ':'เกมของเพื่อนยังดำเนินต่อระหว่างที่คุณพัก'):'สนามรบจะรอคุณกลับมา';if(!net.session||net.session.host)return originals.pause(value);if(!game||game.finished)return;net.localPause=value;$('pauseOverlay').hidden=!value;keys.clear();joystick={x:0,y:0};$('joystick').firstElementChild.style.transform='';};
canvas.addEventListener('pointerdown',e=>{if(net.session&&!net.session.host&&game&&!game.finished&&!game.paused&&!net.localPause&&!game.player.dead&&e.button===0)queueCommand('walk',{point:canvasPoint(e)});});
$('soloMode').onclick=()=>selectMode('solo');$('onlineMode').onclick=()=>selectMode('online');$('startBtn').onclick=()=>startGame();$('createRoomBtn').onclick=()=>enterRoom(true);$('joinRoomBtn').onclick=()=>enterRoom(false);$('leaveRoomBtn').onclick=()=>leaveRoom();$('exitBtn').onclick=$('againBtn').onclick=()=>lobby();$('saveConfigBtn').onclick=async()=>{if(!net.session)return;try{await requestApi(`rooms/${net.session.code}/config`,'POST',roomConfig());networkMessage('ยืนยันตัวเลือกแล้ว');await pollRoom();}catch(error){networkMessage(error.message);}};$('copyRoomBtn').onclick=async()=>{try{await navigator.clipboard.writeText(net.session.code);networkMessage('คัดลอกรหัสแล้ว ส่งรหัสพร้อมลิงก์เกมให้เพื่อน');}catch{networkMessage('รหัสห้อง: '+net.session.code);}};
setInterval(()=>{if(!net.session)return;const delay=game&&!game.finished?250:1000;if(Date.now()-net.lastPoll<delay)return;net.lastPoll=Date.now();void pollRoom();},100);
window.addEventListener('pagehide',()=>{if(net.session){void fetch(`/api/rooms/${net.session.code}/leave`,{method:'POST',headers:{authorization:'Bearer '+net.session.token,'content-type':'application/json'},body:'{}',keepalive:true});}});
